```go
func tlsConfig(token *skupperv2alpha1.AccessToken) *tls.Config {
    caPool := x509.NewCertPool()
    caPool.AppendCertsFromPEM([]byte(token.Spec.Ca))
    return &tls.Config{
        RootCAs:    caPool,
        MinVersion: tls.VersionTLS13,
    }
}
